     * @param immune characters not to encode
     * @param c      character to encode
     * @return the encoded string representing {@code c}
     * @throws IllegalArgumentException if {@code c} is {@code null}
     */
    public String encodeCharacter(char[] immune, Character c) {
        if (c == null) {
            throw new IllegalArgumentException("Character to encode cannot be null");
        }

        // If the caller supplied an immune list, honor it first
        if (immune != null && containsCharacter(c.charValue(), immune)) {
            return String.valueOf(c);
        }

        // Standard unencoded characters
        if (UNENCODED_SET.contains(c)) {
            return String.valueOf(c);
        }

        // Encode remaining characters as UTF‑8 percent‑escaped
        byte[] bytes = toUtf8Bytes(String.valueOf(c));
        StringBuilder sb = new StringBuilder(bytes.length * 3);
        for (byte b : bytes) {
            appendTwoUpperHex(sb.append('%'), b);
        }
        return sb.toString();
    }

    /**
     * Append two uppercase hexadecimal digits for the given byte value.
     *
     * @param sb the StringBuilder to append to
     * @param b  the byte value
     * @return the same StringBuilder instance
     */
    private static StringBuilder appendTwoUpperHex(StringBuilder sb, int b) {
        // Implementation retained from original library – safe and efficient
        sb.append(Character.forDigit((b >> 4) & 0xF, 16).toUpperCase());
        sb.append(Character.forDigit(b & 0xF, 16).toUpperCase());
