import javax.ws.rs.ext.RuntimeDelegate;
import java.util.regex.Pattern;

public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate {

    // other methods

    /** 
     * Validates a media type token according to RFC 7230.
     * Accepts the wildcard "*" or a string composed solely of
     * token characters: ALPHA / DIGIT / "!#$%&'*+-.^_`|~".
     */
    private static final Pattern TOKEN_PATTERN =
            Pattern.compile("^[A-Za-z0-9!#$%&'*+\\-.^_`|~]+$");

    protected static boolean isValid(String str) {
        if (str == null || str.isEmpty()) {
            return false;
        }
        // Allow the wildcard character used for media type matching
        if ("*".equals(str)) {
            return true;
        }
        // Reject any string containing CR or LF or other control characters
        // and enforce the RFC 7230 token character set.
        return TOKEN_PATTERN.matcher(str).matches();
    }

