import javax.naming.Context;
import javax.naming.NamingException;
import javax.naming.ldap.InitialLdapContext;
import javax.naming.ldap.LdapContext;
import javax.naming.ldap.StartTlsRequest;
import javax.naming.ldap.StartTlsResponse;
import org.neo4j.server.security.enterprise.log.SecurityLog;

public class LdapRealm extends DefaultLdapRealm implements RealmLifecycle, ShiroAuthorizationInfoProvider
{
    private final SecurityLog securityLog;

    // other methods

    /**
     * Creates an {@link LdapContext} that uses STARTTLS and performs a real bind
     * with the supplied credentials.  The method now validates that the
     * credentials are non‑null, performs the TLS negotiation before any
     * authentication, and forces a lookup to trigger the bind.  Any failure
     * results in the context being closed and a descriptive exception being
     * thrown.
     *
     * @param ldapContextFactory the factory providing LDAP configuration
     * @param principal          the user DN or bind name
     * @param credentials        the user password
     * @return a fully authenticated {@link LdapContext}
     * @throws NamingException if the context cannot be created or authentication fails
     */
    private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory,
                                                    Object principal,
                                                    Object credentials) throws NamingException {
        if (!(principal instanceof String)) {
            throw new IllegalArgumentException("Principal must be a String");
        }
        if (!(credentials instanceof String)) {
            throw new IllegalArgumentException("Credentials must be a String");
        }

        JndiLdapContextFactory jndiLdapContextFactory = (JndiLdapContextFactory) ldapContextFactory;
        Hashtable<String, Object> env = new Hashtable<>();
        env.put(Context.INITIAL_CONTEXT_FACTORY, jndiLdapContextFactory.getContextFactoryClassName());
        env.put(Context.PROVIDER_URL, jndiLdapContextFactory.getUrl());
        env.put(Context.SECURITY_AUTHENTICATION, jndiLdapContextFactory.getAuthenticationMechanism());
        env.put(Context.SECURITY_PRINCIPAL, principal);
        env.put(Context.SECURITY_CREDENTIALS, credentials);

        LdapContext ctx = null;
        try {
            // Create the context with credentials; authentication will occur on first operation
            ctx = new InitialLdapContext(env, null);

            // Negotiate STARTTLS
            StartTlsRequest startTlsRequest = new StartTlsRequest();
            StartTlsResponse tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
            tls.negotiate();

            // Force a simple operation to trigger authentication
            ctx.lookup("");

            return ctx;
        } catch (AuthenticationException ae) {
            // Authentication failed – close context and rethrow
            LdapUtils.closeContext(ctx);
            securityLog.warn(withRealm("LDAP authentication failed for '%s' on '%s': %s",
                    principal, server(jndiLdapContextFactory), ae.getMessage()));
            throw ae;
        } catch (IOException ioe) {
            LdapUtils.closeContext(ctx);
            securityLog.error(withRealm("Failed to negotiate TLS connection with '%s': %s",
                    server(jndiLdapContextFactory), ioe.getMessage()), ioe);
            throw new CommunicationException(ioe.getMessage(), ioe);
        } catch (Throwable t) {
            LdapUtils.closeContext(ctx);
            securityLog.error(withRealm("Unexpected failure to negotiate TLS connection with '%s': %s",
                    server(jndiLdapContextFactory), t.getMessage()), t);
            throw t;
        }
    }

    // other methods
}
```

