/**
 * Renderer implementation that safely compiles XSLT templates.
 */
public class XsltRenderer implements Renderer {

    // A single, thread‑safe factory instance is sufficient because we configure it
    // for secure processing before each use.
    private static final TransformerFactory TRANSFORMER_FACTORY = TransformerFactory.newInstance();

    // other methods

    /**
     * Creates a {@link Transformer} from the supplied XSLT template stream.
     *
     * <p>The method enforces secure processing settings on the {@link TransformerFactory}
     * to prevent external entity resolution and other unsafe features that could lead
     * to remote code execution. It also ensures that the input stream is closed
     * regardless of success or failure.</p>
     *
     * @param templateStream the XSLT template as an {@link InputStream}
     * @return a configured {@link Transformer}
     * @throws IOException if the stream cannot be read or closed
     * @throws ProcessingFailedException if the XSLT cannot be compiled
     */
    private static Transformer createTransformer(InputStream templateStream)
            throws IOException {
        if (templateStream == null) {
            throw new IllegalArgumentException("Template stream must not be null");
        }

        // Configure the factory for secure processing on each call
        try {
            TRANSFORMER_FACTORY.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
            // Disallow external DTDs and stylesheets
            TRANSFORMER_FACTORY.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            TRANSFORMER_FACTORY.setAttribute(XMLConstants.ACCESS_EXTERNAL_STYLESHEET, "");
        } catch (IllegalArgumentException | UnsupportedOperationException e) {
            // If the underlying implementation does not support the feature,
            // fail fast to avoid running insecure transformations.
            throw new ProcessingFailedException(
                    "Failed to enable secure processing on TransformerFactory", e);
        }

        try {
            // Compile the XSLT template
            return TRANSFORMER_FACTORY.newTransformer(new StreamSource(templateStream));
        } catch (TransformerConfigurationException e) {
            throw new ProcessingFailedException("Failed to create XSLT template", e);
        } finally {
            // Ensure the stream is always closed
            templateStream.close();
        }
    }

    // other methods

}
